export const MNN_SECTIONS = [
  { id: 1, label: "Section 1", lessonRange: "Lessons 1–5", lessons: [1, 2, 3, 4, 5], theme: "Basics & Survival", emoji: "🌸" },
  { id: 2, label: "Section 2", lessonRange: "Lessons 6–10", lessons: [6, 7, 8, 9, 10], theme: "Daily Life", emoji: "🍵" },
  { id: 3, label: "Section 3", lessonRange: "Lessons 11–15", lessons: [11, 12, 13, 14, 15], theme: "Describing & Comparing", emoji: "🏯" },
  { id: 4, label: "Section 4", lessonRange: "Lessons 16–20", lessons: [16, 17, 18, 19, 20], theme: "Experiences & States", emoji: "🗻" },
  { id: 5, label: "Section 5", lessonRange: "Lessons 21–25", lessons: [21, 22, 23, 24, 25], theme: "Expressions & Subclauses", emoji: "🚅" },
];

export const getCardsForSection = (sectionId, level = null) => {
  const section = MNN_SECTIONS.find(s => s.id === parseInt(sectionId, 10));
  if (!section) return [];
  const cards = [];
  section.lessons.forEach(lNum => {
    const lesson = mnnLessons.find(l => l.lessonNum === lNum);
    if (lesson) {
      lesson.words.forEach(w => {
        if (!level || w.jlptLevel === level) {
          cards.push({ ...w, lessonNum: lesson.lessonNum, lessonTitle: lesson.title, lessonTheme: lesson.theme });
        }
      });
    }
  });
  return cards;
};

export const getCardCountForSection = (sectionId, level = null) => {
  return getCardsForSection(sectionId, level).length;
};
